using AudioGuide.Data;
using Microsoft.EntityFrameworkCore;
namespace AudioGuide.Business;
public static class Seed
{
    public static async Task Run(AppDbContext db, string username, string password)
    {
        if (db.Database.IsRelational()) await db.Database.MigrateAsync(); else await db.Database.EnsureCreatedAsync();
        await using var transaction = db.Database.IsRelational() ? await db.Database.BeginTransactionAsync() : null;
        if (!await db.AdminUsers.AnyAsync()) { if (password.Length < 12) throw new Exception("ADMIN_PASSWORD cần ít nhất 12 ký tự"); db.AdminUsers.Add(new() { Username = username, PasswordHash = BCrypt.Net.BCrypt.HashPassword(password), FullName = "Quản trị viên", Role = "Admin" }); await db.SaveChangesAsync(); }
        if (await db.Languages.AnyAsync()) { if (transaction != null) await transaction.CommitAsync(); return; }
        var codes = new[] { "vi", "en", "ko", "ja", "zh", "th" }; var names = new[] { "Tiếng Việt", "English", "한국어", "日本語", "简体中文", "ไทย" }; var voices = new[] { "vi-VN", "en-US", "ko-KR", "ja-JP", "zh-CN", "th-TH" };
        for (int i = 0; i < 6; i++) db.Languages.Add(new() { Code = codes[i], Name = names[i], NativeName = names[i], TtsVoiceCode = voices[i], IsDefault = i == 0 }); await db.SaveChangesAsync();
        string[][] titles = [["Bưu điện Trung tâm Sài Gòn", "Saigon Central Post Office", "사이공 중앙우체국", "サイゴン中央郵便局", "西贡中央邮局", "ไปรษณีย์กลางไซ่ง่อน"], ["Dinh Độc Lập", "Independence Palace", "통일궁", "統一会堂", "统一宫", "ทำเนียบอิสรภาพ"], ["Nhà thờ Đức Bà", "Notre-Dame Cathedral", "노트르담 대성당", "サイゴン大教会", "西贡圣母大教堂", "มหาวิหารน็อทร์ดาม"], ["Chợ Bến Thành", "Ben Thanh Market", "벤탄 시장", "ベンタイン市場", "滨城市场", "ตลาดเบ๊นถั่ญ"], ["Bảo tàng Lịch sử", "History Museum", "역사박물관", "歴史博物館", "历史博物馆", "พิพิธภัณฑ์ประวัติศาสตร์"], ["Phố đi bộ Nguyễn Huệ", "Nguyen Hue Walking Street", "응우옌후에 보행자 거리", "グエンフエ歩行者通り", "阮惠步行街", "ถนนคนเดินเหงียนเหวะ"]];
        string[][] texts = [
        ["Bưu điện Trung tâm được xây dựng từ năm 1886 đến 1891, là một dấu ấn kiến trúc của Sài Gòn. Hãy quan sát mái vòm cao, các bản đồ cổ trên tường và những quầy giao dịch vẫn hoạt động. Công trình kết hợp phong cách châu Âu với trang trí địa phương.","Built between 1886 and 1891, the Central Post Office is a landmark of Saigon. Look up at the vaulted ceiling and the historical maps on the walls. The building combines European architecture with local decorative details and still operates as a post office.","중앙우체국은 1886년부터 1891년 사이에 건설된 사이공의 대표 건축물입니다. 높은 아치형 천장과 벽의 옛 지도를 살펴보세요. 유럽 건축과 현지 장식이 어우러져 있으며 지금도 우체국으로 운영됩니다.","中央郵便局は1886年から1891年にかけて建設されたサイゴンの名所です。高いアーチ天井と壁の古い地図をご覧ください。ヨーロッパ建築と地元の装飾が融合し、現在も郵便局として営業しています。","中央邮局建于1886年至1891年，是西贡的地标。请欣赏高耸的拱形天花板和墙上的历史地图。这座建筑融合欧洲风格与本地装饰，至今仍提供邮政服务。","ไปรษณีย์กลางสร้างขึ้นระหว่างปี ค.ศ. 1886 ถึง 1891 เป็นสัญลักษณ์ของไซ่ง่อน ชมเพดานโค้งสูงและแผนที่เก่าบนผนัง อาคารผสมผสานสถาปัตยกรรมยุโรปกับศิลปะท้องถิ่น และยังเปิดให้บริการไปรษณีย์"],
 ["Dinh Độc Lập gắn với sự kiện ngày 30 tháng 4 năm 1975. Công trình hiện nay do kiến trúc sư Ngô Viết Thụ thiết kế, khánh thành năm 1966. Không gian gồm phòng tiếp khách, phòng làm việc và hệ thống hầm, lưu giữ nhiều dấu tích lịch sử.","Independence Palace is associated with the events of April 30, 1975. Designed by architect Ngo Viet Thu and inaugurated in 1966, it preserves reception rooms, offices and an underground bunker that offer a window into Vietnam's modern history.","통일궁은 1975년 4월 30일의 역사적 사건과 관련된 장소입니다. 건축가 응오비엣투가 설계하여 1966년에 완공되었습니다. 접견실, 집무실, 지하 벙커에서 베트남 현대사의 흔적을 만날 수 있습니다.","統一会堂は1975年4月30日の出来事と深く結びついています。建築家ゴー・ヴィエット・トゥーが設計し、1966年に完成しました。接見室、執務室、地下壕からベトナムの現代史を学べます。","统一宫与1975年4月30日的历史事件紧密相连。现建筑由吴曰树设计，1966年落成。接待室、办公室和地下掩体保留着越南现代历史的痕迹。","ทำเนียบอิสรภาพเกี่ยวข้องกับเหตุการณ์วันที่ 30 เมษายน ค.ศ. 1975 ออกแบบโดยสถาปนิกโง เวียด ถู และเปิดในปี ค.ศ. 1966 ภายในมีห้องรับรอง ห้องทำงาน และบังเกอร์ใต้ดินที่บอกเล่าประวัติศาสตร์เวียดนามยุคใหม่"],
 ["Nhà thờ Đức Bà được xây dựng từ năm 1877 đến 1880 với gạch đỏ đặc trưng. Hai tháp chuông là điểm nhận diện nổi bật của quảng trường Công xã Paris. Khi tham quan, hãy giữ yên lặng và tôn trọng không gian tôn giáo; một số khu vực có thể hạn chế trong thời gian trùng tu.","Notre-Dame Cathedral was built between 1877 and 1880 and is known for its red brick facade and twin bell towers. Please respect this place of worship. Access to some areas may be restricted during restoration.","노트르담 대성당은 1877년부터 1880년 사이에 건설되었으며 붉은 벽돌 외벽과 두 종탑으로 유명합니다. 종교 공간을 존중하고 조용히 관람해 주세요. 보수 공사 중에는 일부 구역의 출입이 제한될 수 있습니다.","サイゴン大教会は1877年から1880年に建設され、赤レンガの外壁と二つの鐘楼が特徴です。礼拝の場を尊重し、静かに見学してください。修復中は一部の区域への立ち入りが制限される場合があります。","圣母大教堂建于1877年至1880年，以红砖外墙和双钟楼闻名。请尊重宗教场所，保持安静。修缮期间部分区域可能限制进入。","มหาวิหารน็อทร์ดามสร้างระหว่างปี ค.ศ. 1877 ถึง 1880 โดดเด่นด้วยอิฐแดงและหอระฆังคู่ โปรดรักษาความสงบและเคารพสถานที่ประกอบศาสนกิจ บางพื้นที่อาจปิดระหว่างการบูรณะ"],
 ["Chợ Bến Thành hiện nay khánh thành năm 1914. Tháp đồng hồ ở cửa Nam là một biểu tượng quen thuộc của thành phố. Bên trong là nhiều gian hàng ẩm thực, vải vóc, đồ thủ công và quà lưu niệm. Hãy hỏi giá trước khi mua và giữ gìn tư trang.","The present Ben Thanh Market opened in 1914. Its southern clock tower is a familiar city symbol. Inside you will find food stalls, fabrics, handicrafts and souvenirs. Ask prices before buying and keep your belongings secure.","현재의 벤탄 시장은 1914년에 문을 열었습니다. 남문 시계탑은 도시의 상징입니다. 내부에는 음식, 직물, 수공예품, 기념품 가게가 있습니다. 구매 전에 가격을 확인하고 소지품에 주의하세요.","現在のベンタイン市場は1914年に開業しました。南門の時計塔は街のシンボルです。市場では料理、布地、工芸品、お土産が並んでいます。購入前に値段を確認し、持ち物にご注意ください。","现在的滨城市场于1914年开业，南门钟楼是城市的象征。市场内有美食、布料、手工艺品和纪念品。购买前请询问价格并保管好随身物品。","ตลาดเบ๊นถั่ญแห่งปัจจุบันเปิดในปี ค.ศ. 1914 หอนาฬิกาประตูใต้เป็นสัญลักษณ์ของเมือง ภายในมีอาหาร ผ้า งานฝีมือ และของที่ระลึก ควรสอบถามราคาก่อนซื้อและระวังทรัพย์สิน"],
 ["Bảo tàng Lịch sử mở cửa năm 1929, nằm cạnh Thảo Cầm Viên. Các bộ sưu tập giới thiệu lịch sử và văn hóa Việt Nam qua nhiều thời kỳ, cùng hiện vật của các nền văn hóa trong khu vực. Hãy kiểm tra lịch mở cửa và quy định chụp ảnh khi đến tham quan.","Opened in 1929 beside the botanical gardens, the History Museum presents Vietnam's history across different periods and artifacts from regional cultures. Check opening schedules and photography rules before visiting.","역사박물관은 동식물원 옆에 위치하며 1929년에 개관했습니다. 다양한 시대의 베트남 역사와 문화, 주변 지역의 유물을 소개합니다. 방문 전에 개관 시간과 촬영 규정을 확인하세요.","歴史博物館は動植物園の隣にあり、1929年に開館しました。各時代のベトナムの歴史や地域文化の遺物を紹介しています。開館時間と撮影規則を事前に確認してください。","历史博物馆于1929年开放，位于动植物园旁。馆藏展示越南各时期的历史文化以及周边地区的文物。参观前请确认开放时间和摄影规定。","พิพิธภัณฑ์ประวัติศาสตร์เปิดในปี ค.ศ. 1929 ตั้งอยู่ข้างสวนพฤกษศาสตร์ จัดแสดงประวัติศาสตร์เวียดนามในยุคต่าง ๆ และโบราณวัตถุจากวัฒนธรรมในภูมิภาค โปรดตรวจสอบเวลาเปิดและกฎการถ่ายภาพก่อนเข้าชม"],
 ["Phố đi bộ Nguyễn Huệ được đưa vào sử dụng năm 2015, nối khu vực trụ sở Ủy ban Nhân dân thành phố với bến Bạch Đằng. Đây là không gian sinh hoạt cộng đồng, lễ hội và đường hoa dịp Tết. Buổi tối là thời điểm thích hợp để cảm nhận nhịp sống đô thị.","Opened in 2015, Nguyen Hue Walking Street connects the City Hall area with Bach Dang Wharf. It hosts community activities, festivals and the Tet flower street. Visit in the evening to experience the city's lively atmosphere.","응우옌후에 보행자 거리는 2015년에 개장하여 시청과 박당 부두를 연결합니다. 지역 행사와 축제, 설날 꽃 거리로 사랑받습니다. 저녁에 방문하면 활기찬 도시 분위기를 느낄 수 있습니다.","グエンフエ歩行者通りは2015年に開設され、市庁舎周辺とバクダン埠頭を結びます。市民活動や祭り、テトの花祭りが行われます。夜には街の活気を感じられます。","阮惠步行街于2015年开放，连接市政厅周边与白藤码头。这里举办社区活动、节庆和春节花街。傍晚是感受城市活力的好时光。","ถนนคนเดินเหงียนเหวะเปิดในปี ค.ศ. 2015 เชื่อมบริเวณศาลาว่าการกับท่าเรือบั๊กดั่ง เป็นพื้นที่กิจกรรมชุมชน เทศกาล และถนนดอกไม้ช่วงตรุษญวน ช่วงเย็นเหมาะสำหรับสัมผัสชีวิตที่คึกคักของเมือง"] ];
        double[] lat = [10.7799, 10.7770, 10.7798, 10.7725, 10.7875, 10.7740], lng = [106.6999, 106.6955, 106.6990, 106.6980, 106.7050, 106.7036]; int[] radii = [60, 100, 60, 80, 80, 120]; string[] slugs = ["buu-dien-trung-tam", "dinh-doc-lap", "nha-tho-duc-ba", "cho-ben-thanh", "bao-tang-lich-su", "nguyen-hue"]; string[] addresses = ["2 Công xã Paris, Quận 1", "135 Nam Kỳ Khởi Nghĩa, Quận 1", "01 Công xã Paris, Quận 1", "Đường Lê Lợi, Quận 1", "2 Nguyễn Bỉnh Khiêm, Quận 1", "Đường Nguyễn Huệ, Quận 1"];
        var langs = await db.Languages.OrderBy(x => x.Id).ToListAsync(); for (int i = 0; i < 6; i++) { var p = new Location { Slug = slugs[i], Latitude = lat[i], Longitude = lng[i], RadiusM = radii[i], Priority = 6 - i, DisplayOrder = i + 1, Address = addresses[i], OpeningHours = i == 5 ? "24/7" : "Vui lòng kiểm tra lịch chính thức trước khi đến", ImageUrl = $"/images/{slugs[i]}.svg" }; db.Locations.Add(p); await db.SaveChangesAsync(); for (int j = 0; j < 6; j++) db.Translations.Add(new() { LocationId = p.Id, LanguageId = langs[j].Id, Name = titles[i][j], ShortDescription = texts[i][j].Split(new[] { '.', '。' }, 2)[0] + ".", NarrationText = texts[i][j], HistoryText = texts[i][j], Status = "Published" }); }
        await db.SaveChangesAsync(); if (transaction != null) await transaction.CommitAsync();
    }
}
